export const VOICE_CLIPS = Object.freeze({
  "natalie-3f203679": { url: clip0, speaker: "natalie", text: "Shane & Natalie’s Pumpkin Patch. A little darkness, a lot of heart.", duration: 4.848 },
  "natalie-eb5ac376": { url: clip1, speaker: "natalie", text: "Welcome to our pumpkin patch! It’s always a warm October night here, and our pumpkins glow.", duration: 6.288 },
  "shane-003da683": { url: clip2, speaker: "shane", text: "And the neighbours are monsters. Lovely ones, honestly. They wander up the path to buy our pumpkins.", duration: 7.176 },
  "natalie-9efb1fe5": { url: clip3, speaker: "natalie", text: "Plant the plots, then tap the big pumpkin or Boost to hurry them along. Harvest when they’re ripe.", duration: 6.0 },
  "shane-b296fa90": { url: clip4, speaker: "shane", text: "Skyla sells them at her stall, and later in our own shop, the Honest Pumpkin. She runs the till. Mostly by sitting on it.", duration: 8.688 },
  "natalie-5a46a113": { url: clip5, speaker: "natalie", text: "Coins go on upgrades for the farm, and on turning our little cottage into a wonderfully haunted home.", duration: 6.288 },
  "shane-2c45b56b": { url: clip6, speaker: "shane", text: "The neighbours ask favours too. Nat keeps them in the journal, very neatly. And as the patch levels up, new attractions open.", duration: 9.264 },
  "natalie-a2ddd6e3": { url: clip7, speaker: "natalie", text: "The goal? The most loved pumpkin patch in the valley. Not world domination, Shane.", duration: 5.256 },
  "narrator-931f24e5": { url: clip8, speaker: "narrator", text: "Mothlight Village. Over the hill from your farm", duration: 3.12 },
  "narrator-dc501e11": { url: clip9, speaker: "narrator", text: "Hollow Green. The square, the well and the noticeboard", duration: 3.6 },
  "narrator-15f705cf": { url: clip10, speaker: "narrator", text: "Elowen's library. A conservatory, one day", duration: 2.928 },
  "narrator-3301d3ef": { url: clip11, speaker: "narrator", text: "Rowan's workshop. More plans than walls", duration: 2.712 },
  "narrator-cd00124a": { url: clip12, speaker: "narrator", text: "The Velvet Bat. A tavern for bats and night folk · Vesper keeps the door", duration: 5.208 },
  "narrator-1d6e78ca": { url: clip13, speaker: "narrator", text: "Carnival Moor. Corvus's tents and the Baron's manor · level 12", duration: 4.8 },
  "narrator-6ce3e809": { url: clip14, speaker: "narrator", text: "Mirror Marsh. Where the observatory waits · level 15", duration: 4.608 },
  "narrator-b4064982": { url: clip15, speaker: "narrator", text: "Lantern Quarry. Beyond the broken bridge · opens at level 9", duration: 3.912 },
  "narrator-257260a6": { url: clip16, speaker: "narrator", text: "Moonroot Copse. Mabel and Tansy, behind the brambles · level 6", duration: 5.04 },
  "narrator-f86727c8": { url: clip17, speaker: "narrator", text: "…and beyond", duration: 1.128 },
  "narrator-6c295b07": { url: clip18, speaker: "narrator", text: "Welcome to Mothlight", duration: 1.416 },
  "elowen-76499ff1": { url: clip19, speaker: "elowen", text: "Ah, there you are. The moths said you'd come this way.", duration: 3.168 },
  "elowen-429a6a37": { url: clip20, speaker: "elowen", text: "Good evening. Mind the ink on the noticeboard; it's still deciding what it says.", duration: 4.656 },
  "elowen-4486afdb": { url: clip21, speaker: "elowen", text: "You've brought the smell of pumpkins with you. The moths approve.", duration: 3.456 },
  "elowen-67645387": { url: clip22, speaker: "elowen", text: "Shh. Listen. That's the almanac turning a page by itself.", duration: 3.72 },
  "elowen-b05b7fef": { url: clip23, speaker: "elowen", text: "Oh! For me? I'll press a page of the almanac around it so it's remembered properly.", duration: 4.464 },
  "elowen-61dfa22d": { url: clip24, speaker: "elowen", text: "You've no idea how long I've wanted one of these. The moths are dancing, look.", duration: 4.248 },
  "elowen-3e9dc23f": { url: clip25, speaker: "elowen", text: "This is going on the good shelf. Thank you, truly.", duration: 3.672 },
  "elowen-b0b8e3e7": { url: clip26, speaker: "elowen", text: "How thoughtful. I'll make a note of it in the margins.", duration: 3.216 },
  "elowen-4835892d": { url: clip27, speaker: "elowen", text: "Lovely. That'll keep a long night's reading company.", duration: 3.168 },
  "elowen-a0100323": { url: clip28, speaker: "elowen", text: "Thank you. Small kindnesses are the best ink.", duration: 2.808 },
  "elowen-ccc8ceb4": { url: clip29, speaker: "elowen", text: "Oh, thank you. I'll find a place for it.", duration: 2.208 },
  "elowen-7b867eb8": { url: clip30, speaker: "elowen", text: "That's kind of you. I'm sure someone will treasure it.", duration: 3.12 },
  "elowen-c20db526": { url: clip31, speaker: "elowen", text: "Ah. It's... very fragrant. The pages may never recover.", duration: 4.296 },
  "elowen-b5172715": { url: clip32, speaker: "elowen", text: "Thank you, I think. Perhaps Rowan would like it more.", duration: 3.024 },
  "elowen-c0f80a2f": { url: clip33, speaker: "elowen", text: "The ink in my letters won't stay still. It wanders about the page looking for better words.", duration: 5.784 },
  "elowen-2a9a4948": { url: clip34, speaker: "elowen", text: "Do you ever write things down, out there on your farm?", duration: 2.976 },
  "elowen-af64b4e1": { url: clip35, speaker: "elowen", text: "Truth, mostly. Sometimes rhyme. Once it ran off to underline a pumpkin pie recipe.", duration: 5.304 },
  "elowen-07fd6f6b": { url: clip36, speaker: "elowen", text: "Takings are a kind of story too. Every coin was a visitor who smiled.", duration: 4.848 },
  "elowen-39e4bbb6": { url: clip37, speaker: "elowen", text: "Ha! Clever ink. I'd stay put for a cat too.", duration: 2.856 },
  "elowen-b999ddd6": { url: clip38, speaker: "elowen", text: "Every moth in Mothlight has a name. I keep them in a ledger.", duration: 3.36 },
  "elowen-f2a92c63": { url: clip39, speaker: "elowen", text: "That one on your shoulder is Parsnip.", duration: 2.208 },
  "elowen-0c182baa": { url: clip40, speaker: "elowen", text: "By the way they circle a lamp. Parsnip goes widdershins. He's a rebel.", duration: 4.704 },
  "elowen-b3181378": { url: clip41, speaker: "elowen", text: "He says he'll pay in dust. That's how moths pay everything.", duration: 2.856 },
  "elowen-5dbfde73": { url: clip42, speaker: "elowen", text: "He'll remember that. Moths have long memories for short lives.", duration: 3.768 },
  "elowen-86b59c6c": { url: clip43, speaker: "elowen", text: "The almanac only records things that are truly shared. Suppers, repairs, good mornings.", duration: 5.16 },
  "elowen-9b581e9b": { url: clip44, speaker: "elowen", text: "It's been blank for years. Lately it's been filling up.", duration: 3.024 },
  "elowen-67ab8ac8": { url: clip45, speaker: "elowen", text: "People stopped visiting one another. Nobody quarrelled; we simply forgot to knock.", duration: 4.512 },
  "elowen-0bbb2be0": { url: clip46, speaker: "elowen", text: "That's exactly what I hoped you'd say. I've a new nib ready.", duration: 3.168 },
  "elowen-79159d93": { url: clip47, speaker: "elowen", text: "It records shared naps. Rowan once filled three pages on a bench.", duration: 4.464 },
  "elowen-6f2d62c1": { url: clip48, speaker: "elowen", text: "I watched your patch from the hill road. All those lanterns in the dark, like a second sky.", duration: 6.192 },
  "elowen-8f520169": { url: clip49, speaker: "elowen", text: "Do the pumpkins mind being carved?", duration: 2.112 },
  "elowen-fcbdca79": { url: clip50, speaker: "elowen", text: "I think they feel chosen. There are worse things to be.", duration: 3.216 },
  "elowen-315295f1": { url: clip51, speaker: "elowen", text: "I believe you. You can tell by the faces. Kind hands carve kind smiles.", duration: 5.4 },
  "elowen-ebfcd533": { url: clip52, speaker: "elowen", text: "Then the whole of the Moonlight row is in trouble.", duration: 2.76 },
  "elowen-0e4f7675": { url: clip53, speaker: "elowen", text: "Rowan mends everybody's things but his own. His door's been on one hinge since spring.", duration: 4.656 },
  "elowen-4a159bea": { url: clip54, speaker: "elowen", text: "Don't tell him I said so.", duration: 1.488 },
  "elowen-aec0d805": { url: clip55, speaker: "elowen", text: "Quietly is the only way. He'd bolt like a spooked hen otherwise.", duration: 3.6 },
  "elowen-0854a291": { url: clip56, speaker: "elowen", text: "I think he's afraid that if he finishes his own house, he'll have to live in it.", duration: 4.248 },
  "elowen-bc893aee": { url: clip57, speaker: "elowen", text: "Wicked. Accurate, but wicked.", duration: 2.064 },
  "elowen-23bcf9ca": { url: clip58, speaker: "elowen", text: "My lantern's flame is a moth that never sleeps. Don't worry, she volunteered.", duration: 4.464 },
  "elowen-e9b60d09": { url: clip59, speaker: "elowen", text: "She likes you. She's burning a shade warmer.", duration: 2.76 },
  "elowen-68791107": { url: clip60, speaker: "elowen", text: "At dawn she naps in the wick. That's why mornings look so pale.", duration: 4.248 },
  "elowen-6fa14d54": { url: clip61, speaker: "elowen", text: "She heard. See? Positively golden.", duration: 2.208 },
  "elowen-5f825e26": { url: clip62, speaker: "elowen", text: "She can spell 'hello' in smoke. Badly. She's working on the 'h'.", duration: 4.464 },
  "elowen-b99cab31": { url: clip63, speaker: "elowen", text: "I've been rebinding the village's old stories. Some of the pages are missing.", duration: 4.416 },
  "elowen-88d95504": { url: clip64, speaker: "elowen", text: "Not lost, I think. Hiding until someone's ready to read them.", duration: 3.6 },
  "elowen-8c38b7dd": { url: clip65, speaker: "elowen", text: "The pages do. They're terribly fussy. One waited forty years for a librarian with clean gloves.", duration: 5.808 },
  "elowen-7506a1df": { url: clip66, speaker: "elowen", text: "You're closer than you think. They flutter whenever you walk past the shelves.", duration: 4.296 },
  "elowen-34a73b8c": { url: clip67, speaker: "elowen", text: "I have. They stained. We don't talk about it.", duration: 2.712 },
  "elowen-09b0a87b": { url: clip68, speaker: "elowen", text: "The moon over Mothlight is the same one over your farm, you know. Just closer.", duration: 4.704 },
  "elowen-cf72a201": { url: clip69, speaker: "elowen", text: "On clear nights I swear I can see your scarecrow waving.", duration: 3.264 },
  "elowen-eeaca2e4": { url: clip70, speaker: "elowen", text: "Then he waves beautifully. Very convincing straw.", duration: 3.12 },
  "elowen-e8238439": { url: clip71, speaker: "elowen", text: "Mothlight sits a little nearer the edge of the map. Things are closer at the edges.", duration: 4.416 },
  "elowen-cffdfc1b": { url: clip72, speaker: "elowen", text: "So do I. It makes the road between us feel shorter.", duration: 3.36 },
  "elowen-b5f01ded": { url: clip73, speaker: "elowen", text: "Your Skyla sounds formidable. The moths say she sold a pumpkin to a fog bank.", duration: 5.04 },
  "elowen-b9ac8b9f": { url: clip74, speaker: "elowen", text: "Is that true?", duration: 1.08 },
  "elowen-c1afc580": { url: clip75, speaker: "elowen", text: "Of course it did. Fog has no pockets but excellent manners.", duration: 3.36 },
  "elowen-25d4f40b": { url: clip76, speaker: "elowen", text: "Then she should come and sell some to Rowan's door hinge.", duration: 3.072 },
  "elowen-aa4efac9": { url: clip77, speaker: "elowen", text: "Parsnip. He's a dreadful gossip, but he's never been wrong.", duration: 3.264 },
  "elowen-0b4b552d": { url: clip78, speaker: "elowen", text: "I've started a study for the village children. Well, child. Well, ghost child.", duration: 5.208 },
  "elowen-27c68687": { url: clip79, speaker: "elowen", text: "She reads upside down and insists it's the correct way.", duration: 3.168 },
  "elowen-66be3790": { url: clip80, speaker: "elowen", text: "For ghosts it is. Gravity's more of a suggestion when you're mostly mist.", duration: 4.752 },
  "elowen-dc5951f8": { url: clip81, speaker: "elowen", text: "I'm lucky to have her. She asks the best questions.", duration: 2.928 },
  "elowen-ec92e432": { url: clip82, speaker: "elowen", text: "Then you two will get on famously.", duration: 2.16 },
  "elowen-f1eb26dd": { url: clip83, speaker: "elowen", text: "The letter I wrote to the village, years ago. I never finished it.", duration: 3.456 },
  "elowen-bbc48e8d": { url: clip84, speaker: "elowen", text: "I keep thinking the last line will come to me, and then it hides.", duration: 3.408 },
  "elowen-80a730dd": { url: clip85, speaker: "elowen", text: "Maybe it does. You've found three pages already. Perhaps the fourth is shy of me, not you.", duration: 6.048 },
  "elowen-c346e135": { url: clip86, speaker: "elowen", text: "Something like 'come home'. But softer. Home is a heavy word on paper.", duration: 4.848 },
  "elowen-1969bb18": { url: clip87, speaker: "elowen", text: "...That's horribly charming. I'll consider it.", duration: 2.76 },
  "elowen-01819c91": { url: clip88, speaker: "elowen", text: "When the Green was full, we held a lantern night every autumn. Every window lit, every door open.", duration: 6.288 },
  "elowen-fd23bc3c": { url: clip89, speaker: "elowen", text: "I'd love to see it again.", duration: 1.488 },
  "elowen-520c15af": { url: clip90, speaker: "elowen", text: "Then it'll be the brightest the Green has ever been. Promise me a seat by the well.", duration: 4.848 },
  "elowen-7a6e5da6": { url: clip91, speaker: "elowen", text: "Fewer windows, then fewer lanterns, then nobody to light them. These things fade quietly.", duration: 5.856 },
  "elowen-e24ed1f9": { url: clip92, speaker: "elowen", text: "That was more or less the whole programme, yes.", duration: 2.904 },
  "elowen-f8b71843": { url: clip93, speaker: "elowen", text: "I don't show anyone the almanac's first page. It's in my handwriting from when I was very young.", duration: 5.808 },
  "elowen-8f57267b": { url: clip94, speaker: "elowen", text: "But I'd like you to see it.", duration: 1.368 },
  "elowen-94021b27": { url: clip95, speaker: "elowen", text: "Gently is how it was written. Look: 'Mothlight, where everybody knocks.'", duration: 4.608 },
  "elowen-e100afce": { url: clip96, speaker: "elowen", text: "A list of everyone in the village and what made them laugh. I'd forgotten half of it.", duration: 4.344 },
  "elowen-8e931d80": { url: clip97, speaker: "elowen", text: "A moth in a top hat. He was very dashing. I was nine.", duration: 3.864 },
  "elowen-9a69c50f": { url: clip98, speaker: "elowen", text: "They called me the moth witch as a joke once. I decided to keep it.", duration: 4.056 },
  "elowen-f8c47339": { url: clip99, speaker: "elowen", text: "A name is only a costume until you grow into it.", duration: 2.808 },
  "elowen-098e7625": { url: clip100, speaker: "elowen", text: "The night I stayed up with a sick moth and it lived. I felt enormous.", duration: 4.512 },
  "elowen-1791cd70": { url: clip101, speaker: "elowen", text: "Thank you. From you, that means a great deal.", duration: 2.808 },
  "elowen-94bb9475": { url: clip102, speaker: "elowen", text: "You're there. Fully ripened.", duration: 1.92 },
  "elowen-9e682987": { url: clip103, speaker: "elowen", text: "Would you mind if I visited your farm one evening? Just to sit by the patch and read.", duration: 4.992 },
  "elowen-0eaf33fd": { url: clip104, speaker: "elowen", text: "I'd bring biscuits.", duration: 1.32 },
  "elowen-3ffabd5a": { url: clip105, speaker: "elowen", text: "Biscuits are never optional. But thank you. I'll bring the good ones.", duration: 3.864 },
  "elowen-d1cf8b73": { url: clip106, speaker: "elowen", text: "Ha! A fair toll. I'll pay it gladly.", duration: 2.568 },
  "elowen-0d13fbfd": { url: clip107, speaker: "elowen", text: "Old harvest songs. I think your pumpkins would like to hear them.", duration: 3.6 },
  "elowen-b91ed91e": { url: clip108, speaker: "elowen", text: "Can I tell you something silly? I'm frightened of finishing things.", duration: 3.768 },
  "elowen-2b035cd7": { url: clip109, speaker: "elowen", text: "Finished things can't change any more. Unfinished things can still become anything.", duration: 5.16 },
  "elowen-89b03ab4": { url: clip110, speaker: "elowen", text: "...Yes. I think that's the line I was missing. Thank you.", duration: 3.504 },
  "elowen-2a5ba0ba": { url: clip111, speaker: "elowen", text: "Yes. If I finish it, someone might read it. Someone might not come.", duration: 4.248 },
  "elowen-10461a18": { url: clip112, speaker: "elowen", text: "I've seen your teacups. That's not fear, that's chaos.", duration: 3.168 },
  "elowen-7174a8cf": { url: clip113, speaker: "elowen", text: "Parsnip has decided he lives on your hat now. I've updated the ledger.", duration: 4.344 },
  "elowen-75238a34": { url: clip114, speaker: "elowen", text: "Moth, Parsnip. Address: hat, pumpkin farmer.", duration: 3.12 },
  "elowen-582c31ad": { url: clip115, speaker: "elowen", text: "He's offering two dusts and a compliment. I'd take it.", duration: 3.624 },
  "elowen-602e5d1f": { url: clip116, speaker: "elowen", text: "He knows. He told the others. You may get more lodgers.", duration: 2.976 },
  "elowen-b95f0543": { url: clip117, speaker: "elowen", text: "As long as the light's kind. Yours seems very kind.", duration: 3.456 },
  "elowen-4525856c": { url: clip118, speaker: "elowen", text: "The Green feels like the Green again. Doors knocking, lanterns lit, Rowan whistling.", duration: 5.736 },
  "elowen-6a7907d5": { url: clip119, speaker: "elowen", text: "The almanac's run out of pages twice this month.", duration: 2.904 },
  "elowen-ce4e325f": { url: clip120, speaker: "elowen", text: "Ours. That's the word the almanac keeps writing. Ours.", duration: 4.296 },
  "elowen-19dd8d0c": { url: clip121, speaker: "elowen", text: "I bind another. I've never been happier to buy glue.", duration: 3.072 },
  "elowen-58002607": { url: clip122, speaker: "elowen", text: "I've ordered one the size of a door. Rowan's building the shelf.", duration: 3.672 },
  "rowan-61e3fcca": { url: clip123, speaker: "rowan", text: "Evening! Mind the sawdust, it's got ideas.", duration: 3.36 },
  "rowan-e4a2193c": { url: clip124, speaker: "rowan", text: "There's my favourite farmer. Don't tell the crows.", duration: 3.912 },
  "rowan-6d3fd078": { url: clip125, speaker: "rowan", text: "Ah, hello! I was just about to start something and not finish it.", duration: 3.912 },
  "rowan-e7fc375c": { url: clip126, speaker: "rowan", text: "Come in, come in. Well, there's no door. Come near, then.", duration: 4.008 },
  "rowan-9cc9de65": { url: clip127, speaker: "rowan", text: "For me? You shouldn't have. No, really, I'll be unbearable about it.", duration: 5.808 },
  "rowan-b50f5963": { url: clip128, speaker: "rowan", text: "Oh, now that's the good stuff. My stuffing's all a-flutter.", duration: 3.72 },
  "rowan-0f32f585": { url: clip129, speaker: "rowan", text: "I'll keep this right by the workbench where I can see it. Thank you, friend.", duration: 4.752 },
  "rowan-5cd84235": { url: clip130, speaker: "rowan", text: "Well, that's grand. Thank you kindly.", duration: 2.52 },
  "rowan-93913ca4": { url: clip131, speaker: "rowan", text: "Lovely! That'll go down a treat after a long day of sawing.", duration: 4.008 },
  "rowan-d615b2fb": { url: clip132, speaker: "rowan", text: "You're too good to me. Don't stop.", duration: 2.328 },
  "rowan-2fa82e35": { url: clip133, speaker: "rowan", text: "That's kind of you. I'll find it a nice shelf.", duration: 2.856 },
  "rowan-7a352398": { url: clip134, speaker: "rowan", text: "Thank you! I'm sure it'll come in handy for something.", duration: 3.552 },
  "rowan-d1ab194f": { url: clip135, speaker: "rowan", text: "Ah. That's a bit... warm, for a fellow made of straw.", duration: 4.704 },
  "rowan-98f8a697": { url: clip136, speaker: "rowan", text: "Thank you. I'll keep it at arm's length. For safety.", duration: 3.6 },
  "rowan-83f0bd81": { url: clip137, speaker: "rowan", text: "You've noticed my door. Everyone notices my door.", duration: 3.552 },
  "rowan-d0030848": { url: clip138, speaker: "rowan", text: "It's not broken, it's... resting.", duration: 2.928 },
  "rowan-e02ed421": { url: clip139, speaker: "rowan", text: "It's a very relaxed door. I'm jealous, honestly.", duration: 3.864 },
  "rowan-d6b8acbd": { url: clip140, speaker: "rowan", text: "One day, aye. One day I'll let someone help me. Gosh, that sounded brave.", duration: 6.432 },
  "rowan-fa6b618b": { url: clip141, speaker: "rowan", text: "I lent it to Mabel for a hat. She made the hat. I made a draught.", duration: 5.16 },
  "rowan-ff43d037": { url: clip142, speaker: "rowan", text: "The crows and I have an arrangement. They don't eat my stuffing, I don't flap at them.", duration: 5.256 },
  "rowan-7c546a9c": { url: clip143, speaker: "rowan", text: "Strictly business.", duration: 1.32 },
  "rowan-5b659356": { url: clip144, speaker: "rowan", text: "Their lawyer. Big fellow, very glossy. Charged me in buttons.", duration: 5.736 },
  "rowan-184c700c": { url: clip145, speaker: "rowan", text: "Only Tuesdays. Tuesday crows are a law unto themselves.", duration: 4.416 },
  "rowan-540d0cfc": { url: clip146, speaker: "rowan", text: "We are. They sing at the sawmill. Out of tune, but with feeling.", duration: 5.4 },
  "rowan-696e390d": { url: clip147, speaker: "rowan", text: "Is it true you grow pumpkins the size of a wheelbarrow?", duration: 3.672 },
  "rowan-b8d7a75c": { url: clip148, speaker: "rowan", text: "I've been dying to build a wheelbarrow the size of a pumpkin.", duration: 3.36 },
  "rowan-4cdf62c6": { url: clip149, speaker: "rowan", text: "A medium pumpkin in a medium barrow. The dream.", duration: 4.248 },
  "rowan-b33dfbf8": { url: clip150, speaker: "rowan", text: "Carve it into a doorway. My own pumpkin door. Smells better than oak.", duration: 5.64 },
  "rowan-026e6b5b": { url: clip151, speaker: "rowan", text: "You'd do that? Oh, my stuffing's gone all wobbly.", duration: 3.912 },
  "rowan-a3160da8": { url: clip152, speaker: "rowan", text: "Every tool in my box has a name. That's Mallory the mallet, and that's Pip the plane.", duration: 6.096 },
  "rowan-976c638f": { url: clip153, speaker: "rowan", text: "Don't tell Elowen. She'll want to write them in a ledger.", duration: 3.312 },
  "rowan-8e5bb140": { url: clip154, speaker: "rowan", text: "Blast! Pip'll be famous now. He'll be insufferable.", duration: 4.152 },
  "rowan-d4a79711": { url: clip155, speaker: "rowan", text: "Old Crook the chisel. She's chipped, but she knows where the grain wants to go.", duration: 5.448 },
  "rowan-b2292167": { url: clip156, speaker: "rowan", text: "Ha! They're a grand crew. Never late, never complain. Unlike me.", duration: 6.696 },
  "rowan-fec13396": { url: clip157, speaker: "rowan", text: "We used to get a cart from your side of the hill every week. Pumpkins, apples, gossip.", duration: 6.432 },
  "rowan-57a84730": { url: clip158, speaker: "rowan", text: "Then the road got quiet.", duration: 1.584 },
  "rowan-85f51331": { url: clip159, speaker: "rowan", text: "Now that's the best thing I've heard since the crows learned harmony.", duration: 3.72 },
  "rowan-cb77c2aa": { url: clip160, speaker: "rowan", text: "The bridge washed out, then the farmer moved on, then... well. Roads forget, if no one walks them.", duration: 8.232 },
  "rowan-94811866": { url: clip161, speaker: "rowan", text: "Ha! Bring a horn. The owls'll love it.", duration: 3.072 },
  "rowan-f89f1ee7": { url: clip162, speaker: "rowan", text: "People think being made of straw's a nuisance. It's not. I never need a pillow.", duration: 5.496 },
  "rowan-7a6ffac8": { url: clip163, speaker: "rowan", text: "Bit of a worry near bonfires, mind.", duration: 2.664 },
});
